  <View style={styles.actions}>{!submission.uncertain&&!confirmed?<PremiumButton title="Kontrollereignis verbindlich dokumentieren" loading={submission.busy} disabled={writeBlocked||!form.kind||!may(form.kind)} onPress={save}/>:null}</View>
