function EvaluationMeasureScopePicker({source,value,disabled,onChange}:{source:ControlSource;value:string;disabled:boolean;onChange:(v:string)=>void}){
 const styles=useTreatmentCorrectionStyles();try{validateEvaluationControlSnapshot(source.snapshot,String(source.snapshot.tenant_id),String(source.snapshot.client_id));const s=source.snapshot;
 return <View style={styles.group}><SourcePicker label="Umfang des Evaluationsauftrags" rows={[{id:'',label:'Alle Originalmaßnahmen erneut bewerten'},...(s.draft.entry?.measureReviews?s.plan.measures.map(m=>({id:m.id!,label:`${m.title} · ${m.id}`})):[])]} value={value} onChange={onChange} disabled={disabled}/><Text style={styles.body}>Die Auswahl wird mit dem Auftrag festgehalten und bleibt auch bei Wiedereröffnung unverändert. Für historische Gesamtbefunde ohne Einzelbewertungen ist nur der Gesamtumfang möglich.</Text></View>;
 }catch(e){return <InfoBanner variant="error" message={e instanceof Error?e.message:'Originalmaßnahme nicht lesbar.'}/>;}
}
